<?php

declare(strict_types=1);

namespace Architex\Platform\Forms;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use PDO;
use Throwable;

final readonly class FormService
{
    public function __construct(private PDO $pdo){}

    /** @return list<array<string,mixed>> */
    public function listTemplates(string $organisationId,string $userId):array{$this->member($organisationId,$userId);$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id FROM form_templates WHERE status='verified' AND (organisation_id IS NULL OR organisation_id=UNHEX(:organisation_id)) ORDER BY category,name,version");$s->execute(['organisation_id'=>$organisationId]);return array_map(fn(string$id):array=>$this->template($organisationId,$id),$s->fetchAll(PDO::FETCH_COLUMN));}
    /** @return list<array<string,mixed>> */
    public function listDrafts(string $organisationId,string $userId,?string $projectId=null):array{$this->member($organisationId,$userId);$sql='SELECT LOWER(HEX(id)) id FROM form_drafts WHERE organisation_id=UNHEX(:organisation_id)'.($projectId===null?'':' AND project_id=UNHEX(:project_id)').' ORDER BY created_at DESC,id';$p=['organisation_id'=>$organisationId];if($projectId!==null){$projectId=$this->id($projectId,'form_project_invalid');$this->project($organisationId,$projectId);$p['project_id']=$projectId;}$s=$this->pdo->prepare($sql);$s->execute($p);return array_map(fn(string$id):array=>$this->getDraft($organisationId,$userId,$id),$s->fetchAll(PDO::FETCH_COLUMN));}
    /** @return array<string,mixed> */
    public function createDraft(string $organisationId,string $userId,string $role,array $input):array{$this->writer($organisationId,$userId,$role);$projectId=$this->id($input['projectId']??null,'form_project_required');$snapshot=$this->snapshot($organisationId,$projectId,$userId);$template=$this->template($organisationId,$this->id($input['templateId']??null,'form_template_required'));$title=$this->text($input['title']??null,220,'form_title_required');$values=$this->values($template,$snapshot,$input['values']??[]);$id=Identifier::generate();$this->transaction(function()use($id,$organisationId,$projectId,$template,$title,$values,$snapshot,$userId):void{$this->pdo->prepare("INSERT INTO form_drafts(id,organisation_id,project_id,template_id,title,revision,status,values_json,auto_fill_snapshot,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:template_id),:title,1,'draft',:values,:snapshot,UNHEX(:user_id))")->execute(['id'=>$id,'organisation_id'=>$organisationId,'project_id'=>$projectId,'template_id'=>$template['id'],'title'=>$title,'values'=>$this->json($values),'snapshot'=>$this->json($snapshot),'user_id'=>$userId]);$this->audit($organisationId,$userId,'form.draft_created',$id,['projectId'=>$projectId,'templateId'=>$template['id'],'revision'=>1]);});return$this->getDraft($organisationId,$userId,$id);}
    /** @return array<string,mixed> */
    public function revise(string $organisationId,string $userId,string $role,string $draftId,array $input):array{$this->writer($organisationId,$userId,$role);$source=$this->getDraft($organisationId,$userId,$draftId);$reason=$this->text($input['reason']??null,500,'form_revision_reason_required');if($source['status']==='superseded')throw new FormException('form_revision_source_invalid');$template=$this->template($organisationId,$source['template']['id']);$updates=$input['values']??[];if(!is_array($updates))throw new FormException('form_values_invalid');$values=$this->values($template,$source['autoFillSnapshot'],array_replace($source['values'],$updates),true);$id=Identifier::generate();$revision=(int)$source['revision']+1;$this->transaction(function()use($id,$organisationId,$source,$draftId,$revision,$values,$reason,$userId):void{$update=$this->pdo->prepare("UPDATE form_drafts SET status='superseded' WHERE id=UNHEX(:id) AND status<>'superseded'");$update->execute(['id'=>$draftId]);if($update->rowCount()!==1)throw new FormException('form_revision_source_invalid');$this->pdo->prepare("INSERT INTO form_drafts(id,organisation_id,project_id,template_id,parent_draft_id,title,revision,status,values_json,auto_fill_snapshot,revision_reason,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:template_id),UNHEX(:parent_id),:title,:revision,'draft',:values,:snapshot,:reason,UNHEX(:user_id))")->execute(['id'=>$id,'organisation_id'=>$organisationId,'project_id'=>$source['projectId'],'template_id'=>$source['template']['id'],'parent_id'=>$draftId,'title'=>$source['title'],'revision'=>$revision,'values'=>$this->json($values),'snapshot'=>$this->json($source['autoFillSnapshot']),'reason'=>$reason,'user_id'=>$userId]);$this->audit($organisationId,$userId,'form.revised',$id,['supersedes'=>$draftId,'revision'=>$revision,'reason'=>$reason]);});return$this->getDraft($organisationId,$userId,$id);}
    /** @return array<string,mixed> */
    public function submitForReview(string $organisationId,string $userId,string $role,string $draftId,string $reason):array{return$this->transition($organisationId,$userId,$role,$draftId,'draft','review_required','form.submitted_for_review','review_reason',$this->text($reason,500,'form_review_reason_required'));}
    /** @return array<string,mixed> */
    public function approve(string $organisationId,string $userId,string $role,string $draftId,bool $humanConfirmed,string $reason):array{if(!$humanConfirmed)throw new FormException('form_approval_confirmation_required');$reason=$this->text($reason,500,'form_approval_reason_required');$this->writer($organisationId,$userId,$role);$draft=$this->getDraft($organisationId,$userId,$draftId);if($draft['status']!=='review_required')throw new FormException('form_not_reviewable');$this->transaction(function()use($draftId,$organisationId,$userId,$reason):void{$update=$this->pdo->prepare("UPDATE form_drafts SET status='approved',approved_by=UNHEX(:user_id),approved_at=UTC_TIMESTAMP(6),approval_reason=:reason WHERE id=UNHEX(:id) AND status='review_required'");$update->execute(['user_id'=>$userId,'reason'=>$reason,'id'=>$draftId]);if($update->rowCount()!==1)throw new FormException('form_not_reviewable');$this->audit($organisationId,$userId,'form.approved',$draftId,['reason'=>$reason]);});return$this->getDraft($organisationId,$userId,$draftId);}
    /** @return array<string,mixed> */
    public function issue(string $organisationId,string $userId,string $role,string $draftId,bool $humanConfirmed,string $reason):array{if(!$humanConfirmed)throw new FormException('form_issue_confirmation_required');$reason=$this->text($reason,500,'form_issue_reason_required');$this->writer($organisationId,$userId,$role);$draft=$this->getDraft($organisationId,$userId,$draftId);if($draft['status']!=='approved')throw new FormException('form_not_approved');$hash=hash('sha256',$this->json(['id'=>$draftId,'template'=>$draft['template'],'revision'=>$draft['revision'],'values'=>$draft['values'],'autoFillSnapshot'=>$draft['autoFillSnapshot'],'approvedBy'=>$draft['approvedBy'],'approvalReason'=>$draft['approvalReason'],'issueReason'=>$reason]));$this->transaction(function()use($draftId,$organisationId,$userId,$reason,$hash,$draft):void{$update=$this->pdo->prepare("UPDATE form_drafts SET status='issued',issued_by=UNHEX(:user_id),issued_at=UTC_TIMESTAMP(6),issue_reason=:reason,audit_hash=:hash WHERE id=UNHEX(:id) AND status='approved'");$update->execute(['user_id'=>$userId,'reason'=>$reason,'hash'=>$hash,'id'=>$draftId]);if($update->rowCount()!==1)throw new FormException('form_not_approved');$json=$this->json(['title'=>$draft['title'],'revision'=>$draft['revision'],'template'=>$draft['template'],'values'=>$draft['values'],'autoFillSnapshot'=>$draft['autoFillSnapshot'],'auditHash'=>$hash,'signatureStatus'=>'not_configured']);$html=$this->html($draft,$hash);$insert=$this->pdo->prepare('INSERT INTO form_exports(id,organisation_id,form_draft_id,format,content,checksum,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:draft_id),:format,:content,:checksum,UNHEX(:user_id))');foreach(['html'=>$html,'json'=>$json]as$format=>$content)$insert->execute(['id'=>Identifier::generate(),'organisation_id'=>$organisationId,'draft_id'=>$draftId,'format'=>$format,'content'=>$content,'checksum'=>hash('sha256',$content),'user_id'=>$userId]);$this->audit($organisationId,$userId,'form.issued',$draftId,['auditHash'=>$hash,'reason'=>$reason,'formats'=>['html','json'],'signatureStatus'=>'not_configured']);});return$this->getDraft($organisationId,$userId,$draftId);}
    /** @return list<array<string,mixed>> */
    public function listExports(string $organisationId,string $userId,string $draftId):array{$draft=$this->getDraft($organisationId,$userId,$draftId);if($draft['status']!=='issued')return[];$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,format,checksum,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt FROM form_exports WHERE organisation_id=UNHEX(:organisation_id) AND form_draft_id=UNHEX(:draft_id) ORDER BY FIELD(format,'html','json')");$s->execute(['organisation_id'=>$organisationId,'draft_id'=>$draftId]);return$s->fetchAll();}
    /** @return array<string,mixed> */
    public function export(string $organisationId,string $userId,string $exportId):array{$this->member($organisationId,$userId);$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(form_draft_id)) formDraftId,format,content,checksum FROM form_exports WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$this->id($exportId,'form_export_not_found'),'organisation_id'=>$organisationId]);$row=$s->fetch();if(!is_array($row))throw new FormException('form_export_not_found');return$row;}
    /** @return array<string,mixed> */
    public function getDraft(string $organisationId,string $userId,string $draftId):array{$this->member($organisationId,$userId);$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) projectId,LOWER(HEX(template_id)) templateId,LOWER(HEX(parent_draft_id)) parentDraftId,title,revision,status,values_json,auto_fill_snapshot,revision_reason revisionReason,review_reason reviewReason,LOWER(HEX(approved_by)) approvedBy,approval_reason approvalReason,LOWER(HEX(issued_by)) issuedBy,issue_reason issueReason,audit_hash auditHash,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt FROM form_drafts WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)");$s->execute(['id'=>$this->id($draftId,'form_not_found'),'organisation_id'=>$organisationId]);$row=$s->fetch();if(!is_array($row))throw new FormException('form_not_found');$row['revision']=(int)$row['revision'];$row['values']=json_decode((string)$row['values_json'],true,64,JSON_THROW_ON_ERROR);$row['autoFillSnapshot']=json_decode((string)$row['auto_fill_snapshot'],true,64,JSON_THROW_ON_ERROR);unset($row['values_json'],$row['auto_fill_snapshot']);$row['template']=$this->template($organisationId,(string)$row['templateId']);$row['signatureStatus']='not_configured';return$row;}
    /** @return array<string,mixed> */
    private function transition(string$o,string$u,string$r,string$id,string$from,string$to,string$event,string$column,string$reason):array{$this->writer($o,$u,$r);$draft=$this->getDraft($o,$u,$id);if($draft['status']!==$from)throw new FormException('form_state_invalid');$this->transaction(function()use($o,$u,$id,$from,$to,$event,$column,$reason):void{$s=$this->pdo->prepare("UPDATE form_drafts SET status=:to,$column=:reason WHERE id=UNHEX(:id) AND status=:from");$s->execute(['to'=>$to,'reason'=>$reason,'id'=>$id,'from'=>$from]);if($s->rowCount()!==1)throw new FormException('form_state_invalid');$this->audit($o,$u,$event,$id,['reason'=>$reason]);});return$this->getDraft($o,$u,$id);}
    /** @return array<string,mixed> */
    private function template(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,template_key templateKey,name,category,version,status,field_schema,limitations FROM form_templates WHERE id=UNHEX(:id) AND status='verified' AND (organisation_id IS NULL OR organisation_id=UNHEX(:organisation_id))");$s->execute(['id'=>$id,'organisation_id'=>$o]);$row=$s->fetch();if(!is_array($row))throw new FormException('form_template_not_found');$row['fields']=json_decode((string)$row['field_schema'],true,64,JSON_THROW_ON_ERROR);unset($row['field_schema']);return$row;}
    /** @return array<string,mixed> */
    private function snapshot(string$o,string$p,string$u):array{$this->project($o,$p);$s=$this->pdo->prepare('SELECT project_code projectCode,project_name projectName,client_name clientName,municipality,property_reference propertyReference,property_use propertyUse,current_phase currentPhase FROM projects WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$p,'organisation_id'=>$o]);$project=$s->fetch();$uS=$this->pdo->prepare('SELECT email FROM users WHERE id=UNHEX(:id)');$uS->execute(['id'=>$u]);$email=$uS->fetchColumn();$oS=$this->pdo->prepare('SELECT name FROM organisations WHERE id=UNHEX(:id)');$oS->execute(['id'=>$o]);return['project'=>$project,'user'=>['userId'=>$u,'email'=>$email],'organisation'=>['organisationId'=>$o,'name'=>$oS->fetchColumn()],'capturedAt'=>gmdate('Y-m-d\TH:i:s\Z')];}
    /** @return array<string,string> */
    private function values(array$template,array$snapshot,mixed$input,bool$complete=false):array{if(!is_array($input))throw new FormException('form_values_invalid');$values=[];$allowed=[];foreach($template['fields']as$field){$key=(string)$field['key'];$allowed[$key]=true;$auto=$field['autoFill']??null;$value=$auto===null?null:($auto==='userEmail'?$snapshot['user']['email']:($snapshot['project'][$auto]??null));if(array_key_exists($key,$input))$value=$input[$key];if($value!==null&&(!is_scalar($value)||mb_strlen(trim((string)$value))>12000))throw new FormException('form_field_invalid');$value=trim((string)($value??''));if(($field['required']??false)&&$value===''&&!$complete)throw new FormException('form_required_field_missing');$values[$key]=$value;}foreach($input as$key=>$value)if(!isset($allowed[$key]))throw new FormException('form_field_invalid');foreach($template['fields']as$field)if(($field['required']??false)&&($values[(string)$field['key']]??'')==='')throw new FormException('form_required_field_missing');return$values;}
    private function html(array$draft,string$hash):string{$rows='';foreach($draft['template']['fields']as$field){$key=(string)$field['key'];$rows.='<tr><th>'.htmlspecialchars((string)$field['label'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</th><td>'.nl2br(htmlspecialchars((string)($draft['values'][$key]??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')).'</td></tr>';}return'<!doctype html><html><head><meta charset="utf-8"><title>'.htmlspecialchars((string)$draft['title'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</title></head><body><h1>'.htmlspecialchars((string)$draft['title'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</h1><p>Template '.htmlspecialchars((string)$draft['template']['version'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').' · revision '.(int)$draft['revision'].'</p><table>'.$rows.'</table><p>SHA-256 '.htmlspecialchars($hash,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</p><p>No digital signature provider configured.</p></body></html>';}
    private function project(string$o,string$p):void{$s=$this->pdo->prepare('SELECT 1 FROM projects WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$p,'organisation_id'=>$o]);if($s->fetchColumn()===false)throw new FormException('form_project_not_found');}
    private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new FormException('form_permission_denied');$this->member($o,$u);}
    private function member(string$o,string$u):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation_id) AND user_id=UNHEX(:user_id) AND status='active'");$s->execute(['organisation_id'=>$o,'user_id'=>$u]);if($s->fetchColumn()===false)throw new FormException('form_permission_denied');}
    private function audit(string$o,string$u,string$a,string$id,array$m):void{(new AuditService($this->pdo))->append($o,$u,$a,'form_draft',$id,$m);}
    private function transaction(callable$f):mixed{$this->pdo->beginTransaction();try{$v=$f();$this->pdo->commit();return$v;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
    private function id(mixed$v,string$r):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new FormException($r);return strtolower($v);}
    private function text(mixed$v,int$m,string$r):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new FormException($r);return$v;}
    private function json(array$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
}
